const Fastify = require('fastify');
const { TicketDb } = require('./ticketDb');
const { verifySession } = require('./auth');

const app = Fastify();

app.register(async function supportRoutes(fastify) {
  fastify.addHook('preHandler', async (request, reply) => {
    const user = await verifySession(request);
    if (!user) {
      return reply.status(401).send({ error: 'Authentication required' });
    }
    request.user = user;

    if (request.params && request.params.ticketId) {
      const ticket = await TicketDb.findTicket(request.params.ticketId);
      if (!ticket) {
        return reply.status(404).send({ error: 'Ticket not found' });
      }

      // Check whether user is the customer who filed the ticket or an authorized agent
      const isOwner = ticket.customerId === user.id;
      const isAgent = user.roles && user.roles.includes('SUPPORT_AGENT');
      if (!isOwner && !isAgent) {
        return reply.status(403).send({ error: 'Forbidden: you cannot reply to tickets of other users' });
      }

      request.activeTicket = ticket;
    }
  });

  fastify.post('/api/tickets/:ticketId/replies', async (request, reply) => {
    const { message } = request.body || {};

    const replyRecord = await TicketDb.addReply({
      ticketId: request.activeTicket.id,
      authorId: request.user.id,
      text: message,
      createdAt: new Date()
    });

    return reply.send({ status: 'reply_posted', replyId: replyRecord.id });
  });
});

app.listen({ port: 8094 });
